const CACHE='suomi-v106-dialogs';
const FILES=['./','./index.html','./style.css?v=103','./fonts/dm-sans-latin-wght-normal.woff2','./fonts/dm-sans-latin-ext-wght-normal.woff2','./fonts/fraunces-latin-standard-normal.woff2','./fonts/fraunces-latin-ext-standard-normal.woff2','./impressum.html','./datenschutz.html','./app.js?v=103','./dialogs.mjs?v=1','./dialogs.json','./translation-feedback.mjs?v=1','./word-lookup.mjs?v=2','./endings-practice.mjs?v=1','./lexicon.json','./learning-insights.mjs','./word-practice.mjs?v=59','./wordsearch.mjs','./wordsearch-ui.mjs?v=62','./auth.js?v=98','./classrooms.js?v=72','./classrooms.css?v=69','./quality-review.js?v=1','./duplicate-candidates.json','./supabase-config.js','./review-plan.mjs','./learning-path.mjs','./learning-path-data.mjs','./grammar-topics.mjs','./verbs-data.mjs','./verb-practice.mjs','./verbs.css?v=80','./sentences.json','./grammar.json','./icon.svg','./manifest.webmanifest','./games.mjs?v=1','./games.css?v=1','./games-progress.mjs'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('suomi-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok&&response.type==='basic'&&!response.redirected){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(c=>c.put(event.request,copy)));}return response;}).catch(()=>caches.match(event.request).then(r=>r||(event.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
